const projects=[{slug:'project-black',name:'Project Black',category:'Arts & culture / Exhibition',className:'black-art',description:'A Pan-African art exhibition and cultural experience celebrating African creativity, artistic expression, identity and culture.',organisation:'Client details to be confirmed',services:'Planning · Coordination · Exhibition delivery',art:'PROJECT<br>BLACK',label:'A celebration of African creativity'}, {slug:'light-in-threads',name:'LIGHT IN THREADS 2.0',category:'Fashion / Live experience',className:'threads-art',description:'A two-day Christian fashion and creative event in Abuja, bringing industry learning, runway collections and live performance together.',organisation:'Supernatural Life Church (SLC)',services:'Production · Logistics · Live execution',art:'Light in<br>Threads',label:'Fashion. Expression. Connection.'}];
const capabilities=[['Project management','A clear plan. A shared direction.','Scope development, timelines, budget coordination, resource planning, stakeholder management, progress tracking and delivery oversight.'],['Project execution','Where the plan meets the real world.','On-ground coordination, production management, vendor and team coordination, implementation oversight and deliverable management.'],['Procurement & sourcing','The right resources, in the right place.','Product and material sourcing, supplier coordination, price and availability research, purchase coordination and delivery coordination.'],['Operations & logistics','Every moving part, accounted for.','Site coordination, transportation, scheduling, resource movement, operational planning and on-site support.']];
const steps=[['Understand','Get clear on the idea, the ambition and what success looks like.'],['Plan','Map the timelines, resources, responsibilities and deliverables.'],['Coordinate','Bring the people, partners and moving parts together.'],['Execute','Make it happen on the ground. Solve problems as they arise.'],['Deliver','Bring the project to completion, with the outcome in focus.']];
const eyebrow=t=>`<div class="eyebrow"><span class="dot"></span>${t}</div>`;
const art=p=>p.slug === 'project-black' ? `<div class="art supplied-art"><img src="assets/blvck/dog-in-the-city.png" width="1196" height="1028" alt="Dog in the City: figures with canine heads against a city skyline" decoding="async"></div>` : p.slug === 'light-in-threads' ? `<div class="art supplied-art"><img src="assets/light-in-threads/21-08-07.jpg" width="2560" height="1707" alt="Panel discussion beneath the Illuminate the Unseen event backdrop" decoding="async"></div>` : `<div class="art ${p.className}"><span class="art-label">${p.label}</span><div class="${p.slug==='project-black'?'orbit':'thread'}" aria-hidden="true"></div><strong>${p.art}</strong></div>`;
const card=p=>`<a class="project" href="#projects/${p.slug}">${art(p)}<div class="project-meta"><div><h3>${p.name}</h3><p>${p.category}</p></div><span class="circle-arrow" aria-hidden="true">↗</span></div></a>`;
const closing=()=>`<section class="closing">${eyebrow('The next project could be yours')}<h2>Big idea?<br>Let's get it done.</h2><a class="pill" href="#contact">Start a conversation <span>↗</span></a><span class="big-arrow" aria-hidden="true">↗</span></section>`;
const serviceList=()=>`<div class="services-list">${capabilities.map((c,i)=>`<details><summary><span>0${i+1}</span>${c[0]}<b aria-hidden="true">+</b></summary><p><strong>${c[1]}</strong><br>${c[2]}</p></details>`).join('')}</div>`;
const process=()=>`<div class="process">${steps.map((s,i)=>`<article><span class="eyebrow">0${i+1} ↗</span><h3>${s[0]}</h3><p>${s[1]}</p></article>`).join('')}</div>`;
function home(){return `<section class="studio-hero"><div class="studio-kicker">Independent thinking. Exceptional delivery. <span>Abuja, Nigeria ↗</span></div><h1><span class="hero-line">Big ideas.<span class="word-capsule">Real impact.</span></span><span class="hero-line second-line">All the moving<span class="hero-description">We connect the planning, people and resources that turn ambitious ideas into extraordinary experiences.</span></span><span class="hero-line final-line"><span class="rolling-capsule"><span aria-hidden="true">parts. ✳ parts. ✳ parts. ✳ parts. ✳ </span><span class="sr-only">parts.</span></span><a class="hero-round" href="#projects" aria-label="Explore our work">↘</a></span></h1><div class="studio-baseline"><span>From the first what if. To the final we did it.</span><a class="text-link" href="#projects">Discover the work ↓</a></div></section><section class="section studio-services">${eyebrow('Good ideas deserve great execution.')}<div class="service-cards">${capabilities.map((c,i)=>`<a href="#services"><span class="service-symbol" aria-hidden="true">${['✳','↗','◎','↔'][i]}</span><h2>${c[0]}</h2><p>${c[1]}</p><span class="text-link">Explore capability ↗</span></a>`).join('')}</div></section><section class="section studio-work"><div class="section-top"><div>${eyebrow('Selected projects / 01—02')}<h2>Ideas out<br>in the <em>world.</em></h2></div><a class="pill" href="#projects">All projects <span>↗</span></a></div><div class="projects">${projects.map(card).join('')}</div></section><section class="section studio-about">${eyebrow('The people behind the doing')}<div class="studio-about-copy"><h2>A little less talk.<br>A lot more <span>done.</span></h2><div><p>Between an idea and its execution, there are a hundred moving parts. We bring structure to the complexity, keep everyone moving together, and get the work done.</p><a class="pill" href="#about">Meet Progenius <span>↗</span></a></div></div></section><section class="section studio-process"><div class="section-top"><div>${eyebrow('Our approach')}<h2>Clear thinking.<br>Considered action.</h2></div><p>One shared direction.<br>Every moving part accounted for.</p></div>${process()}</section>${closing()}`;}
document.querySelector('.menu').addEventListener('click',e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);});
const head=(label,title,text='')=>`<section class="page-head">${eyebrow(label)}<h1 class="page-title">${title}</h1>${text?`<p>${text}</p>`:''}</section>`;
function about(){return `${head('This is Progenius','We manage what it takes<br>to make things happen.','We exist for the space between an idea and its successful execution.')}<section class="section"><div class="copy-grid"><h2>Structure for<br>your ambition.</h2><div><p>A project is never just a plan. It is people, decisions, timelines, resources and the unexpected. Progenius brings those moving parts together and manages them towards a clear outcome.</p><p>We can join at the first conversation or at the point where your project needs experienced coordination and hands-on execution support.</p></div></div><div class="copy-grid"><h2>Different worlds.<br>The same commitment.</h2><div><p>From arts and culture to fashion, live experiences, corporate initiatives and community projects, our approach starts with understanding what needs to happen.</p><p>Our capabilities adapt to the project: planning, production, sourcing, logistics, people and delivery.</p></div></div><div class="copy-grid"><h2>How we show up.</h2><div><p><strong>Clarity.</strong> Everyone understands the objective and their part in it.</p><p><strong>Resourcefulness.</strong> We find practical ways through the unexpected.</p><p><strong>Ownership.</strong> We stay focused on execution and the final outcome.</p></div></div></section>${closing()}`;}
function services(){return `${head('Our capabilities','All the moving parts.<br>One team in your corner.','Support throughout the project lifecycle, from shaping the plan to coordinating its delivery.')}<section class="section">${serviceList()}</section><section class="section statement"><div>${eyebrow('The approach')}</div><div><h2>One clear path.<br>From <em>what if</em> to done.</h2><p>Every project is different. A shared process keeps the objective in sight.</p></div></section><section class="section">${process()}</section>${closing()}`;}
function work(){return `${head('Selected projects / 02','The work speaks.','Creative projects. Real-world complexity. Explore the projects behind the Progenius portfolio.')}<section class="section"><div class="projects">${projects.map(card).join('')}</div><p class="caption">Project BLVCK: exhibition artwork. LIGHT IN THREADS 2.0: event photography.</p></section>${closing()}`;}
function caseStudy(p){if(p.slug === 'light-in-threads') return threadsCaseStudy(p); if(p.slug === 'project-black') return blackCaseStudy(p); const next=projects.find(q=>q.slug!==p.slug);return `${head(p.category,p.name,p.description)}<section class="section"><div class="case-art">${art(p)}</div><p class="caption">Concept artwork — not documentary project photography.</p><div class="case-info"><span><strong>Organisation</strong><br>${p.organisation}</span><span><strong>Focus</strong><br>${p.category}</span></div><div class="copy-grid"><h2>The project.</h2><p>${p.description}</p></div><div class="copy-grid"><h2>The delivery story.</h2><div><p>${p.slug==='project-black'?'The case study will explore Progenius’ involvement in planning, coordinating and delivering the exhibition.':'The case study will explore the coordination of creative production, people, schedules, vendors, logistics and live execution.'}</p><div class="notice">Full case study coming soon. The detailed scope, project timeline, responsibilities and outcomes are being confirmed before publication.</div></div></div><div class="copy-grid"><h2>Behind the scenes.</h2><p>Project photography and the complete process story will be added here once approved.</p></div><a class="text-link" href="#projects/${next.slug}">Next project: ${next.name} ↗</a></section>${closing()}`;}
function contact(){return `${head('Start something','Let’s build something.','Tell us what you’re working on and where you need support.')}<section class="section contact-grid"><div><h2>A big ambition.<br>A rough sketch.<br>A tricky brief.</h2><p>Every project starts somewhere.<br>Let’s start with yours.</p><p><a class="text-link contact-email" href="mailto:hello.projenius@gmail.com">hello.projenius@gmail.com ↗</a></p><div class="notice">Email us directly, or use the form to download a project brief and attach it to your email. The form does not send your details automatically.</div></div><form id="enquiry"><div class="form-grid"><label>Your name *<input name="name" autocomplete="name" required maxlength="100"></label><label>Organisation<input name="organisation" autocomplete="organization" maxlength="150"></label><label>Email *<input name="email" autocomplete="email" type="email" required></label><label>Phone number<input name="phone" autocomplete="tel" type="tel"></label><label>Project type *<select name="type" required><option value="">Select project type</option><option>Arts & culture</option><option>Fashion</option><option>Events & experiences</option><option>Community</option><option>Corporate</option><option>Procurement</option><option>Something else</option></select></label><label>Project location<input name="location" placeholder="City / country"></label><label>Estimated timeline<input name="timeline" placeholder="When are you looking to deliver?"></label><label>Budget range (optional)<input name="budget" placeholder="Include your currency"></label><label class="full">Services required<select name="services"><option>Help me work out what I need</option>Project management</option>Project execution</option>Procurement & sourcing</option>Operations & logistics</option>End-to-end support</option></select></label><label class="full">What are you planning? *<textarea name="description" required minlength="15" maxlength="5000" placeholder="The idea, the objective, and where we can help."></textarea></label><label class="honey" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label></div><button class="pill" type="submit">Download project brief <span>↓</span></button><p class="form-note">Your details stay in this page and the file you download.</p><div id="form-status" role="status"></div></form></section>`;}
function render(){const route=(location.hash.slice(1)||'home').replace('projects/lighting-threads','projects/light-in-threads');const p=projects.find(p=>route===`projects/${p.slug}`);const views={home,about,services,projects:work,contact};document.querySelector('#app').innerHTML=p?caseStudy(p):views[route]?views[route]():`${head('Page not found','A small detour.')}<section class="section"><a class="pill" href="#home">Back to home ↗</a></section>`;document.title=`${p?p.name:({home:'From idea to execution.',about:'About',services:'Capabilities',projects:'Our work',contact:'Start a project'}[route]||'Page not found')} — Progenius`;document.querySelector('nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false');document.querySelectorAll('nav a').forEach(a=>{if(a.hash===`#${route}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo(0,0);const form=document.querySelector('#enquiry');if(form)form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);if(data.get('website'))return;const text='PROGENIUS — PROJECT BRIEF\n\n'+Array.from(data).filter(([k])=>k!=='website').map(([k,v])=>`${k.toUpperCase()}\n${v||'Not provided'}\n`).join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='progenius-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Your project brief has been downloaded. Attach it to an email to hello.projenius@gmail.com to send your enquiry.';});}
Object.assign(projects[0], {
  name: 'Project BLVCK',
  art: 'PROJECT<br>BLVCK',
  description: 'A Pan-African exhibition exploring identity, migration and community, announced for Orisun Art Gallery in Abuja.',
  organisation: 'Project BLVCK',
  date: '27 September 2025',
  location: 'Orisun Art Gallery, Tropic Galleria, Abuja',
  convener: 'Richardson Ojeka',
  curator: 'Adebayo Ebenezer Seun',
  leadershipUrl: 'https://leadership.ng/blvck-pan-african-art-exhibition-set-to-light-up-abuja/',
  sunUrl: 'https://thesun.ng/blvck-pan-african-art-exhibition-to-illuminate-abujas-cultural-scene/'
});

function blvckGallery() {
  const pages = [['cover','Exhibition cover'],['page-01','Welcome note'],['page-02','Curator — Seun Adebayo'],['page-03','Convener — Richardson Ojeka'],['page-04','Dog in the City'],['page-05','The African Family'],['page-06','Exhibiting artists'],['back','Exhibition contacts']];
  return `<div class="copy-grid"><h2>From displacement<br>to belonging.</h2><div><p>The exhibition booklet pairs two centrepieces: <em>Dog in the City</em>, reflecting on dignity and identity in migration, and <em>The African Family</em>, celebrating shared rituals, community and kinship.</p><p>These are reproductions of the supplied artworks, not photographs of the exhibition installation.</p></div></div>
  <div class="blvck-artworks">
    <figure><a href="assets/blvck/dog-in-the-city.png" target="_blank" rel="noopener"><img src="assets/blvck/dog-in-the-city.png" width="1196" height="1028" loading="lazy" alt="Dog in the City: canine-headed figures in jackets beneath traffic lights and high-rise buildings"></a><figcaption><strong>Dog in the City</strong><span>View full artwork ↗</span></figcaption></figure>
    <figure><a href="assets/blvck/african-family.png" target="_blank" rel="noopener"><img src="assets/blvck/african-family.png" width="1070" height="918" loading="lazy" alt="The African Family: a dense composition of interwoven figures, dark outlines and vivid color"></a><figcaption><strong>The African Family</strong><span>View full artwork ↗</span></figcaption></figure>
  </div>
  <div class="copy-grid"><h2>The exhibition<br>booklet.</h2><div><p>Explore the welcome note, curator and convener profiles, artwork commentary and artist lineup in the original eight-page programme.</p><p>The cover lists 27 September 2025 at 10:00am, Orisun Art Gallery, Tropic Galleria, Abuja. Contact details in the booklet belong to the exhibition.</p></div></div>
  <div class="booklet-grid">${pages.map(([file,title],i)=>`<a href="assets/blvck/${file}.png" target="_blank" rel="noopener" class="booklet-page"><img src="assets/blvck/${file}.png" width="595" height="842" loading="lazy" alt="${title} — original BLVCK exhibition programme page"><span><small>${String(i+1).padStart(2,'0')}</small>${title}<b aria-hidden="true">↗</b></span></a>`).join('')}</div>`;
}

function blackCaseStudy(p) {
  return `${head(p.category, p.name, p.description)}
  <section class="section">
    <figure class="blvck-hero"><img src="assets/blvck/dog-in-the-city.png" width="1196" height="1028" alt="Dog in the City, an exhibition centrepiece depicting canine-headed figures in a city" fetchpriority="high"><figcaption>Dog in the City · Exhibition centrepiece</figcaption></figure>
    <div class="case-info">
      <span><strong>Announced date</strong><br>${p.date}</span>
      <span><strong>Announced venue</strong><br>${p.location}</span>
      <span><strong>Convener</strong><br>${p.convener}</span>
      <span><strong>Curator</strong><br>${p.curator}</span>
    </div>
    <div class="copy-grid"><h2>Identity.<br>Art. Belonging.</h2><div>
      <p>BLVCK was conceived as a space for African artists to explore self-definition, resilience and the relationships that sustain communities. Its announced programme brought migration and belonging into conversation through visual art.</p>
      <p>LEADERSHIP named social entrepreneur Richardson Ojeka as the convener, alongside artist and curator Adebayo Ebenezer Seun.</p>
      <a class="text-link" href="${p.leadershipUrl}" target="_blank" rel="noopener noreferrer">Read the LEADERSHIP preview ↗</a>
    </div></div>
    <div class="copy-grid"><h2>Inside the<br>programme.</h2><div>
      <p>The Sun’s preview described a planned lineup of Adebayo and 11 other Nigerian artists representing different regions of the country.</p>
      <p><em>Dog in the City</em> explores the uncertainty of migration and the search for opportunity. <em>The African Family</em> centres kinship and shared heritage. The two works were announced as exhibition centrepieces.</p>
      <a class="text-link" href="${p.sunUrl}" target="_blank" rel="noopener noreferrer">Read The Sun’s preview ↗</a>
    </div></div>
    <div class="copy-grid"><h2>The delivery<br>story.</h2><div>
      <p>Progenius’ detailed responsibilities, execution process and project outcomes will be documented here once confirmed.</p>
      <div class="notice">The linked coverage was published ahead of the exhibition. It supports the announced programme, but does not verify final participation, attendance, delivery outcomes or Progenius’ scope of work.</div>
    </div></div>
    ${blvckGallery()}
    <p><a class="text-link" href="#projects/light-in-threads">Next project: LIGHT IN THREADS 2.0 ↗</a></p>
  </section>${closing()}`;
}

const renderContent = render; render = () => { renderContent(); window.progeniusMotion?.(); }; window.addEventListener('hashchange',render);render();
